const controller = new AbortController();
const processes = client.ogcProcesses({ capabilityPolicy: 'strict' });
const run = await processes.execute({ processId: 'geometry.buffer', mode: 'async', inputs, signal: controller.signal });
for await (const snapshot of run.watch({ signal: controller.signal })) console.log(snapshot.status, snapshot.progress);
const results = await run.results({ signal: controller.signal, deadlineMs: 30_000, maxAttempts: 20 });
// Operator cancellation path only: await run.cancel();

var job = await processes.SubmitJobAsync("geometry.buffer", inputs, cancellationToken);
var deadline = DateTimeOffset.UtcNow.AddSeconds(30);
while (job.Status is "accepted" or "running") {
    if (DateTimeOffset.UtcNow >= deadline) throw new TimeoutException("process job deadline exceeded");
    await Task.Delay(TimeSpan.FromMilliseconds(500), cancellationToken);
    job = await processes.GetJobAsync(job.JobId, cancellationToken);
}
if (job.Status != "successful") throw new InvalidOperationException($"job ended {job.Status}");
var result = await processes.GetJobResultsAsync(job.JobId, cancellationToken);
